10	// TestLastInteractionTime_SetOnFirstPrompt verifies that LastInteractionTime is set
11	// when a session is first initialized via UserPromptSubmit.
12	func TestLastInteractionTime_SetOnFirstPrompt(t *testing.T) {
13		t.Parallel()
14		env := NewRepoWithCommit(t)
15		session := env.NewSession()
16	
17		beforePrompt := time.Now()
18		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
19			t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
20		}
21	
22		state, err := env.GetSessionState(session.ID)
23		if err != nil {
24			t.Fatalf("GetSessionState failed: %v", err)
25		}
26		if state == nil {
27			t.Fatal("session state should exist after UserPromptSubmit")
28		}
29	
30		if state.LastInteractionTime == nil {
31			t.Fatal("LastInteractionTime should be set after first prompt")
32		}
33		if state.LastInteractionTime.Before(beforePrompt) {
34			t.Errorf("LastInteractionTime %v should be after test start %v",
35				*state.LastInteractionTime, beforePrompt)
36		}
37	}
38	
39	// TestLastInteractionTime_UpdatedOnSubsequentPrompts verifies that LastInteractionTime
40	// is updated on each subsequent UserPromptSubmit call.
41	func TestLastInteractionTime_UpdatedOnSubsequentPrompts(t *testing.T) {
42		t.Parallel()
43		env := NewRepoWithCommit(t)
44		session := env.NewSession()
45	
46		// First prompt
47		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
48			t.Fatalf("first SimulateUserPromptSubmit failed: %v", err)
49		}
50	
51		state1, err := env.GetSessionState(session.ID)
52		if err != nil {
53			t.Fatalf("GetSessionState after first prompt failed: %v", err)
54		}
55		if state1.LastInteractionTime == nil {
56			t.Fatal("LastInteractionTime should be set after first prompt")
57		}
58		firstInteraction := *state1.LastInteractionTime
59	
60		// Small delay to ensure timestamps differ
61		time.Sleep(10 * time.Millisecond)
62	
63		// Second prompt
64		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
65			t.Fatalf("second SimulateUserPromptSubmit failed: %v", err)
66		}
67	
68		state2, err := env.GetSessionState(session.ID)
69		if err != nil {
70			t.Fatalf("GetSessionState after second prompt failed: %v", err)
71		}
72		if state2.LastInteractionTime == nil {
73			t.Fatal("LastInteractionTime should be set after second prompt")
74		}
75	
76		if !state2.LastInteractionTime.After(firstInteraction) {
77			t.Errorf("LastInteractionTime should be updated: first=%v, second=%v",
78				firstInteraction, *state2.LastInteractionTime)
79		}
80	}
81	
82	// TestLastInteractionTime_PreservedAcrossCheckpoints verifies that LastInteractionTime
83	// survives a full checkpoint cycle (prompt → stop → prompt).
84	func TestLastInteractionTime_PreservedAcrossCheckpoints(t *testing.T) {
85		t.Parallel()
86		env := NewRepoWithCommit(t)
87		session := env.NewSession()
88	
89		// First prompt + checkpoint
90		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
91			t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
92		}
93	
94		env.WriteFile("file1.txt", "content1")
95		session.CreateTranscript("Create file1", []FileChange{
96			{Path: "file1.txt", Content: "content1"},
97		})
98		if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
99			t.Fatalf("SimulateStop failed: %v", err)
100		}
101	
102		time.Sleep(10 * time.Millisecond)
103	
104		// Second prompt
105		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
106			t.Fatalf("second SimulateUserPromptSubmit failed: %v", err)
107		}
108	
109		state, err := env.GetSessionState(session.ID)
110		if err != nil {
111			t.Fatalf("GetSessionState failed: %v", err)
112		}
113		if state.LastInteractionTime == nil {
114			t.Fatal("LastInteractionTime should be set after second prompt")
115		}
116	
117		// LastInteractionTime should be after StartedAt (second prompt is later)
118		if !state.LastInteractionTime.After(state.StartedAt) {
119			t.Errorf("LastInteractionTime %v should be after StartedAt %v",
120				*state.LastInteractionTime, state.StartedAt)
121		}
122	}
