367	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
368	// When force is true, it amends without prompting.
369	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
370		shortHash := headCommit.Hash.String()[:7]
371		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
372	
373		// Skip amending if this exact checkpoint ID is already in the commit.
374		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
375			if existing.String() == checkpointIDStr {
376				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
377				return nil
378			}
379		}
380	
381		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
382	
383		amend := true
384		if !force {
385			form := NewAccessibleForm(
386				huh.NewGroup(
387					huh.NewConfirm().
388						Title("Amend the last commit in this branch?").
389						Affirmative("Y").
390						Negative("n").
391						Value(&amend),
392				),
393			)
394			if err := form.Run(); err != nil {
395				return fmt.Errorf("prompt failed: %w", err)
396			}
397		}
398	
399		if !amend {
400			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
401			return nil
402		}
403	
404		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
405	
406		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
407		if output, err := cmd.CombinedOutput(); err != nil {
408			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
409		}
410	
411		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
412		return nil
413	}
